#!/usr/bin/env bash
# ACCESSIBILITÉ — menus du header utilisables au clavier (Qui sommes-nous ?, Nos disciplines, menu du membre ;
# infobulles des cloches au focus) + chapitre « L'accessibilité » ; partie Interface transverse rédigée.
# Prérequis : apply-docs-header.sh.
# Usage (racine du repo) : bash apply-a11y-header.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/app-shell/useDisclosure.ts" 2>/dev/null | grep -qF "export function useDisclosure"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "title: \"Le header\"" "apps/web/content/docs/dev/interface/header.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-header.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/interface/header.mdx" "apps/web/src/features/app-shell/CollaborativeBell.tsx" "apps/web/src/features/app-shell/Header.tsx" "apps/web/src/features/app-shell/NotificationBell.tsx" "apps/web/src/features/app-shell/OurActivitiesMenu.tsx" "apps/web/src/features/app-shell/UserMenu.tsx" "apps/web/src/features/member-documents/DocumentsNavLink.tsx")
CREATED=("apps/web/content/docs/dev/interface/accessibilite.mdx" "apps/web/src/features/app-shell/useDisclosure.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export function useDisclosure" "apps/web/src/features/app-shell/useDisclosure.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/interface"
